insert into public.revision_topics (qualification,subject,board,title,slug,sort_order) values
('GCSE','Maths','Edexcel International',"Numbers and the number system","igcse-numbers-number-system",1),
('GCSE','Maths','Edexcel International',"Algebra","igcse-algebra",2),
('GCSE','Maths','Edexcel International',"Sequences, functions and graphs","igcse-sequences-functions-graphs",3),
('GCSE','Maths','Edexcel International',"Geometry and trigonometry","igcse-geometry-trigonometry",4),
