insert into public.revision_notes(topic_id,content,key_terms) select id,"Number skills include ordering positive and negative values, working with fractions, decimals and percentages, using ratio, rounding to a stated degree of accuracy and expressing values in standard form. Check whether a question requires an exact value or an approximation. When rounding, retain guard digits until the final step. A recurring decimal can be written as a fraction by forming an equation and eliminating the recurring part.",ARRAY["Directed number","Fractions","Percentages","Ratio","Standard form","Bounds","Recurring decimals"]::text[] from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-numbers-number-system" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Write 0.00072 in standard form.",3,"7.2 × 10⁻⁴. Move the decimal point four places to the right to obtain 7.2, so the power is −4.","Standard form is a × 10ⁿ where 1 ≤ a < 10. The original number is smaller than one, so n is negative.",1 from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-numbers-number-system" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Algebra uses symbols to represent numbers and relationships. Collect like terms, expand brackets and factorise expressions. Solve linear equations by applying inverse operations to both sides. For simultaneous linear equations, eliminate one variable or use substitution. Quadratic expressions can be factorised when suitable, solved using the quadratic formula, or interpreted graphically. Inequalities are solved similarly to equations, but multiplying or dividing by a negative number reverses the inequality sign.",ARRAY["Expression","Equation","Identity","Expand","Factorise","Simultaneous equations","Quadratic","Inequality"]::text[] from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-algebra" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Solve 3(2x − 1) = 15.",3,"6x − 3 = 15; 6x = 18; x = 3.","Expand the bracket first, then use inverse operations to isolate x.",1 from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-algebra" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"A sequence follows a rule. For an arithmetic sequence, the difference between consecutive terms is constant and the nth term is linear in n. A function maps each allowed input to one output; its domain is the set of permitted inputs. Linear graphs have constant gradient, while quadratic graphs are parabolas. Use coordinates, intercepts and gradients to interpret graphs and solve equations. Direct and inverse proportion can be represented algebraically and graphically.",ARRAY["Arithmetic sequence","Nth term","Function","Domain","Range","Gradient","Intercept","Direct proportion","Inverse proportion"]::text[] from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-sequences-functions-graphs" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Find the nth term of 5, 8, 11, 14, …",3,"3n + 2.","The common difference is 3, so start with 3n. The first term is 5, requiring an added 2.",1 from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-sequences-functions-graphs" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Geometry questions use angle facts, properties of polygons, similarity, congruence, perimeter, area, surface area and volume. Parallel-line angle rules and circle theorems should be stated when used. Pythagoras' theorem applies to right-angled triangles. Trigonometric ratios relate an angle to side lengths; the sine rule and cosine rule extend triangle calculations beyond right angles. Give units and appropriate accuracy for measurements.",ARRAY["Angle facts","Polygon","Similarity","Congruence","Circle theorem","Pythagoras","Sine rule","Cosine rule","Area","Volume"]::text[] from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-geometry-trigonometry" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"A right-angled triangle has shorter sides 6 cm and 8 cm. Find the hypotenuse.",3,"10 cm, since c² = 6² + 8² = 100 and c = 10.","Apply Pythagoras' theorem and take the positive square root because a length cannot be negative.",1 from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-geometry-trigonometry" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"A vector describes both magnitude and direction. Column vectors can be added and subtracted component by component and multiplied by a scalar. A position vector gives the position of a point relative to an origin. Transformations include translation, reflection, rotation and enlargement; describe each using the required centre, angle, direction, mirror line or scale factor. A combination of transformations must be applied in the stated order.",ARRAY["Vector","Column vector","Position vector","Magnitude","Translation","Reflection","Rotation","Enlargement"]::text[] from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-vectors-transformations" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Add the vectors (3, −2) and (−1, 5).",3,"(2, 3). Add corresponding components: 3 + (−1) = 2 and −2 + 5 = 3.","Vector addition is component-wise; keep the signs of negative components.",1 from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-vectors-transformations" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Statistical work includes collecting and classifying data, choosing suitable diagrams, calculating averages and measures of spread, and interpreting distributions. The mean uses every value, the median is the middle value after ordering, and the mode is the most frequent value. Probability lies between zero and one. For mutually exclusive events, add probabilities; for independent events, multiply them. Use a sample space or tree diagram for multi-stage situations and check that probabilities across all exhaustive outcomes sum to one.",ARRAY["Population","Sample","Mean","Median","Mode","Range","Cumulative frequency","Probability","Mutually exclusive","Independent events"]::text[] from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-statistics-probability" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"A fair six-sided die is rolled. Find the probability of scoring an even number.",3,"3/6 = 1/2.","The even outcomes are 2, 4 and 6: three favourable outcomes out of six equally likely outcomes.",1 from public.revision_topics where qualification='GCSE' and subject='Maths' and board='Edexcel International' and slug="igcse-statistics-probability" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_topics (qualification,subject,board,title,slug,sort_order) values
('A-level','Maths','Edexcel',"Proof","edexcel-proof",1),
('A-level','Maths','Edexcel',"Algebra and functions","edexcel-algebra-functions",2),
('A-level','Maths','Edexcel',"Coordinate geometry","edexcel-coordinate-geometry",3),
('A-level','Maths','Edexcel',"Trigonometry","edexcel-trigonometry",4),
('A-level','Maths','Edexcel',"Differentiation","edexcel-differentiation",5),
('A-level','Maths','Edexcel',"Integration","edexcel-integration",6),
('A-level','Maths','Edexcel',"Vectors","edexcel-vectors",7),
('A-level','Maths','Edexcel',"Statistics and probability","edexcel-statistics-probability",8),
('A-level','Maths','Edexcel',"Mechanics","edexcel-mechanics",9)
insert into public.revision_notes(topic_id,content,key_terms) select id,"Mathematical proof requires a clear chain of logical reasoning. Direct proof starts from accepted facts and derives the result. Proof by exhaustion checks every case in a finite set; proof by contradiction assumes the opposite and derives an impossibility. Use correct notation and distinguish an example from a general proof.",ARRAY["Direct proof","Proof by contradiction","Proof by exhaustion","Counterexample"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-proof" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Show that the sum of two odd integers is even.",3,"Let the integers be 2m + 1 and 2n + 1. Their sum is 2(m+n+1), which is divisible by 2 and therefore even.","Represent arbitrary odd integers algebraically; demonstrate that their sum is twice an integer.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-proof" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"A-level algebra includes indices, surds, polynomials, partial fractions, inequalities and the manipulation of functions. A function has a domain and range. Composite functions apply one mapping after another; inverse functions reverse a one-to-one mapping on an appropriate domain. Sketch and interpret graphs, including transformations and intersections. Use algebraic methods to solve equations and justify restrictions on solutions.",ARRAY["Polynomial","Surd","Partial fractions","Composite function","Inverse function","Domain","Range"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-algebra-functions" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"If f(x)=2x+3 and g(x)=x², find f(g(2)).",3,"g(2)=4, then f(4)=11.","Apply the inner function first, then substitute its output into the outer function.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-algebra-functions" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Coordinate geometry connects algebra with geometric properties. Use gradients, distances and midpoints to analyse straight lines and curves. A straight line can be written in forms such as y=mx+c or ax+by+c=0. Circles can be described by an equation involving the centre and radius. Interpret intersections by solving equations simultaneously.",ARRAY["Gradient","Distance","Midpoint","Equation of a line","Circle equation","Intersection"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-coordinate-geometry" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Find the gradient of the line through (1,2) and (5,10).",3,"(10−2)/(5−1)=8/4=2.","Gradient is change in y divided by change in x.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-coordinate-geometry" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"A-level trigonometry includes radians, exact values, identities, trigonometric equations and graphs. Convert between degrees and radians using π radians = 180°. Use identities such as sin²x + cos²x = 1 to simplify expressions and solve equations. Pay attention to the interval requested and include all valid solutions.",ARRAY["Radians","Sine","Cosine","Tangent","Identity","Exact value","Trigonometric equation"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-trigonometry" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Convert 150° to radians.",3,"150 × π/180 = 5π/6.","Multiply degrees by π/180 and simplify the fraction.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-trigonometry" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Differentiation gives the gradient function. Apply the power, product, quotient and chain rules as appropriate. A stationary point occurs where the derivative is zero. Use the second derivative or a sign change in the first derivative to classify a stationary point. Differentiation also models rates of change and optimisation.",ARRAY["Derivative","Chain rule","Product rule","Quotient rule","Stationary point","Second derivative"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-differentiation" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Differentiate y=4x³−5x²+2.",3,"dy/dx=12x²−10x.","Apply the power rule term by term; the derivative of a constant is zero.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-differentiation" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Integration reverses differentiation. Find indefinite integrals by increasing the power and dividing by the new power, adding a constant of integration. Definite integrals give signed area between a curve and the x-axis. Techniques include substitution and integration by parts. Interpret limits and signs carefully, and use integration to find areas and accumulated quantities.",ARRAY["Antiderivative","Constant of integration","Definite integral","Substitution","Integration by parts","Area"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-integration" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Integrate 6x² with respect to x.",3,"2x³ + C.","Increase the power from 2 to 3 and divide the coefficient by 3.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-integration" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Vectors represent magnitude and direction. Use column vectors and unit vectors, calculate magnitudes, and solve geometric problems using position vectors. Parallel vectors are scalar multiples. In three dimensions, work with i, j and k components. Set out vector arguments clearly and use a diagram where it helps identify relationships.",ARRAY["Column vector","Unit vector","Position vector","Magnitude","Scalar multiple","Parallel vectors"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-vectors" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"Find the magnitude of the vector (3,4).",3,"√(3²+4²)=5.","The magnitude is the square root of the sum of the squared components.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-vectors" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Statistical methods include sampling, data presentation, measures of location and spread, correlation, regression and probability distributions. For a discrete random variable, use its probability distribution to calculate expectations and variance. The binomial distribution models a fixed number of independent trials with constant success probability. The normal distribution is continuous and symmetric; standardisation uses the mean and standard deviation.",ARRAY["Sampling","Correlation","Regression","Expectation","Variance","Binomial distribution","Normal distribution"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-statistics-probability" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"A fair coin is tossed three times. What is the probability of exactly two heads?",3,"3/8. There are three sequences with exactly two heads out of eight equally likely sequences.","Use the binomial model with n=3, p=0.5 and r=2.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-statistics-probability" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
insert into public.revision_notes(topic_id,content,key_terms) select id,"Mechanics models motion and forces. Use consistent SI units and distinguish scalar quantities from vectors. Constant-acceleration motion can be analysed with suvat equations. Newton’s laws connect resultant force, mass and acceleration. Resolve forces into perpendicular components, apply moments where appropriate, and use momentum and energy methods to solve problems.",ARRAY["Displacement","Velocity","Acceleration","Resultant force","Newton\u2019s laws","Momentum","Moment","Suvat"]::text[] from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-mechanics" on conflict(topic_id) do update set content=excluded.content,key_terms=excluded.key_terms,updated_at=now();
insert into public.exam_questions(topic_id,prompt,marks,model_answer,explanation,sort_order) select id,"A particle accelerates from rest at 3 m/s² for 4 s. Find its final speed.",3,"v=u+at=0+3×4=12 m/s.","Use v=u+at with initial speed u=0.",1 from public.revision_topics where qualification='A-level' and subject='Maths' and board='Edexcel' and slug="edexcel-mechanics" on conflict(topic_id,sort_order) do update set prompt=excluded.prompt,marks=excluded.marks,model_answer=excluded.model_answer,explanation=excluded.explanation;
